# EAGLES (reduced)
#
# Portuguese TreeTagger Part-of-Speech Tags (reduced EAGLES tagset) as used by the
# TreeTagger parameter file for Portuguese provided by Pablo Gamallo.
#
# Contractions (tags joined by '+') are mapped according to their first component.
#
# Source: tag list extracted from the TreeTagger model
__META_SOURCE_URL__=https\://www.cis.uni-muenchen.de/~schmid/tools/TreeTagger/data/Portuguese-Tagset.html
__META_TYPE_BASE__=de.tudarmstadt.ukp.dkpro.core.api.lexmorph.type.pos.

# AO0	Adjective, ordinal
AO0=POS_ADJ
# AOS	Adjective, ordinal
AOS=POS_ADJ
